UPDATE goals SET dod = TRIM(COALESCE(dod, '')) || ' Machine check: ' || '{"paths": ["scripts/mirror-guard.py"], "contains": "MIRROR-MISSING-REPAIR-1"}', updated_at = datetime('now') WHERE status = 'adopted' AND goal_key = 'repo-mirror-drift-closeout' AND instr(COALESCE(dod, ''), 'Machine check:') = 0 AND instr(COALESCE(dod, ''), 'SELECT ') = 0;
