UPDATE goals SET dod = TRIM(COALESCE(dod, '')) || ' Machine check: ' || 'SELECT ''0'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_ai_log WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-1 day'')) = 0 THEN ''pending: no ops agent call in 24 hours'' ELSE CAST((SELECT COUNT(*) FROM ops_ai_log WHERE ok = 0 AND ts >= strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-1 day'')) AS TEXT) END AS observed', updated_at = datetime('now') WHERE status = 'adopted' AND goal_key = 'ops-exec-loop-parse-guard' AND instr(COALESCE(dod, ''), 'Machine check:') = 0 AND instr(COALESCE(dod, ''), 'SELECT ') = 0;
UPDATE goals SET dod = TRIM(COALESCE(dod, '')) || ' Machine check: ' || 'SELECT ''0'' AS expected, CAST(COUNT(*) AS TEXT) AS observed FROM agent_issues WHERE title LIKE ''[self-heal] tool web_%'' AND created_at > CAST(strftime(''%s'', ''now'', ''-14 days'') AS INTEGER) * 1000', updated_at = datetime('now') WHERE status = 'adopted' AND goal_key = 'self-heal-tool-list-correction' AND instr(COALESCE(dod, ''), 'Machine check:') = 0 AND instr(COALESCE(dod, ''), 'SELECT ') = 0;
UPDATE goals SET dod = TRIM(COALESCE(dod, '')) || ' Machine check: ' || 'SELECT ''0'' AS expected, CAST(COUNT(*) AS TEXT) AS observed FROM agent_issues WHERE title LIKE ''DEPLOY-UNCOORDINATED%'' AND created_at > CAST(strftime(''%s'', ''now'', ''-1 day'') AS INTEGER) * 1000', updated_at = datetime('now') WHERE status = 'adopted' AND goal_key = 'fleet-loop-actuation-gap' AND instr(COALESCE(dod, ''), 'Machine check:') = 0 AND instr(COALESCE(dod, ''), 'SELECT ') = 0;
UPDATE goals SET dod = TRIM(COALESCE(dod, '')) || ' Machine check: ' || 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM routing_policy WHERE layer GLOB ''L[0-9]'' AND status <> ''LIVE'') AS TEXT) AS observed', updated_at = datetime('now') WHERE status = 'adopted' AND goal_key = 'cost-routing-stack-l0l7' AND instr(COALESCE(dod, ''), 'Machine check:') = 0 AND instr(COALESCE(dod, ''), 'SELECT ') = 0;
UPDATE goals SET dod = TRIM(COALESCE(dod, '')) || ' Machine check: ' || 'SELECT ''1'' AS expected, CASE WHEN CAST((SELECT last_value FROM metric_registry WHERE metric = ''external_impact_per_dollar'') AS REAL) <= 0.012 AND (SELECT last_refreshed FROM metric_registry WHERE metric = ''external_impact_per_dollar'') >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''1'' ELSE ''unmet: external_impact_per_dollar '' || COALESCE((SELECT last_value FROM metric_registry WHERE metric = ''external_impact_per_dollar''), ''?'') || '' (needs <= 0.012, refreshed within 6 hours)'' END AS observed', updated_at = datetime('now') WHERE status = 'adopted' AND goal_key = 'external-impact-per-dollar' AND instr(COALESCE(dod, ''), 'Machine check:') = 0 AND instr(COALESCE(dod, ''), 'SELECT ') = 0;

